SELECT ALL POSITION
FROM PLAYER;

SELECT POSITION
FROM PLAYER;

SELECT DISTINCT POSITION
FROM PLAYER;

SELECT NVL(MAX(MGR), 9999) AS MGR
FROM EMP
WHERE ENAME = 'JSC';

SELECT A.ENAME, A.JOB, A.SAL, B.GRADE
FROM EMP A, SALGRADE B
WHERE A.SAL BETWEEN B.LOSAL AND B.HISAL;

SELECT DEPTNO, A.DNAME, A.LOC, B.DNAME, B.LOC
FROM DEPT A JOIN DEPT_TEMP B
USING (DEPTNO);
